import java.io.IOException;
import java.util.Scanner;

public class SafeCommandRunner {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a command to execute (e.g., 'ls' or 'dir'): ");
        String userInput = scanner.nextLine();

        // Safe: Only allow a predefined set of commands
        String[] allowedCommands = {"ls", "dir", "date"};
        boolean isAllowed = false;

        for (String cmd : allowedCommands) {
            if (userInput.equals(cmd)) {
                isAllowed = true;
                break;
            }
        }

        if (isAllowed) {
            try {
                // Safe: Use a list to avoid command injection
                Process process = Runtime.getRuntime().exec(new String[]{"/bin/sh", "-c", userInput});
                // ... (code to read process output)
            } catch (IOException e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("Command not allowed.");
        }
    }
}
```

